    'ops_deployment_hint' => 'ট্রায়ালের তথ্য যেমন আছে তেমন থাকবে। লাইভ চালুর এই চেকগুলো টাকার হিসাব চালু করে না বা শুরুর ব্যালেন্স অনুমোদন করে না।',
    'ops_go_live_warnings' => 'লাইভ চালুর আগে যা ঠিক করবেন (এগুলো প্রস্তুতি আটকায় না, তবে আসল ব্যবহারের আগে ঠিক করুন)',
    'ops_warn_sms_driver_logging_only' => 'এসএমএস এখনো পাঠানো হচ্ছে না (পরীক্ষা মোড)। পার্টনার লগইন OTP চালুর আগে আসল এসএমএস সার্ভিস সেট করুন।',
    'ops_warn_mail_driver_logging_only' => 'ইমেইল এখনো পাঠানো হচ্ছে না (পরীক্ষা মোড)। কারও পাসওয়ার্ড রিসেট ইমেইল লাগার আগে ইমেইল চালু করুন। টেকনিশিয়ানকে জানান।',
    'ops_warn_mail_from_address_is_example_placeholder' => 'ইমেইল এখনো নমুনা ঠিকানা (@example.com) থেকে যাচ্ছে। কোম্পানির আসল ইমেইল ঠিকানা দিতে টেকনিশিয়ানকে বলুন। টেকনিশিয়ানের জন্য: MAIL_FROM_ADDRESS।',
    'ops_warn_mail_smtp_host_is_local_development' => 'ইমেইল এখনো পরীক্ষার মেইলবক্সে যাচ্ছে, আসল মানুষের কাছে নয়। আসল ইমেইল সার্ভার যুক্ত করতে টেকনিশিয়ানকে বলুন। টেকনিশিয়ানের জন্য: MAIL_HOST (এখন Mailpit)।',
    'ops_warn_login_otp_requires_real_sms_before_go_live' => 'লগইন OTP চালু আছে, কিন্তু এসএমএস এখনো আসলে পাঠানো হচ্ছে না। আসল এসএমএস সার্ভিস দিয়ে OTP পুরোটা পরীক্ষা করুন।',
    'ops_warn_partner_login_otp_forced_off_in_preview' => 'SMS লগইন কোড চালু করা আছে, কিন্তু ট্রায়াল মোড বন্ধ না হওয়া ও SMS চালু না হওয়া পর্যন্ত এটি বন্ধ থাকবে। টেকনিশিয়ানের জন্য: MADINA_PREVIEW_MODE=false।',
    'ops_warn_staff_totp_forced_off_in_preview' => 'ট্রায়াল মোড চালু থাকায় স্টাফ ও মালিকের অ্যাপ কোড দিয়ে লগইন (2FA) বন্ধ থাকবে, কারণ ট্রায়াল মোডে এসএমএস ও ইমেইল বন্ধ। টেকনিশিয়ানের জন্য: MADINA_PREVIEW_MODE।',
    'ops_warn_admin_ip_allowlist_empty' => 'ইন্টারনেটের যে কেউ অ্যাডমিন লগইন পাতা খুলতে পারে। শুধু আপনার অফিসের ইন্টারনেট ঠিকানা থেকে খোলার ব্যবস্থা করতে টেকনিশিয়ানকে বলুন। টেকনিশিয়ানের জন্য: MADINA_ADMIN_IP_ALLOWLIST।',
    'ops_warn_privacy_retention_unconfigured' => 'বন্ধ হওয়া রেকর্ড কত দিন রাখা হবে তা ঠিক করা নেই। তথ্য গোপনীয়তার নিয়ম (PDPO) মানতে টেকনিশিয়ানকে দিন ঠিক করতে বলুন। টেকনিশিয়ানের জন্য: MADINA_PRIVACY_RETENTION_DAYS।',
    'ops_warn_place_code_catalog_incomplete' => 'প্লেস কোডের তালিকা এখনো সম্পূর্ণ নয়। পার্টনাররা আসলে যোগ দেওয়ার আগে প্লেস কোড পাতায় ব্যবস্থাপনা ও এলাকার স্থান তৈরি করুন (টেকনিশিয়ান চাইলে তৈরি বাংলাদেশ তালিকাও যোগ করতে পারেন)।',
    'ops_warn_area_dealer_assignments_missing' => 'এখনো কোনো এরিয়া ডিলার ঠিক করা হয়নি। প্লেস কোড তৈরি হলে বিভাগ, জেলা, উপজেলা বা ইউনিয়ন / পৌরসভায় অন্তত একজন ডিলার দিন। না হলে সেই এলাকার কমিশন কোম্পানির কাছে থেকে যাবে।',
    'ops_warn_area_dealer_coverage_incomplete' => 'এরিয়া ডিলার এখনো সবাইকে ধরে না। কারো বিভাগ বা জেলায় কোনো ডিলার নেই, অথবা একাধিক ডিলার আছে, তাই সেই কমিশন কোম্পানির কাছে থাকে।',
    'ops_warn_partners_missing_place_codes' => 'কিছু সক্রিয় ডিলার/সাব-ডিলারের প্লেস কোড নেই। এলাকার কমিশন লাইভ চালুর আগে আসল প্লেস কোড দিয়ে তাদের অ্যাকাউন্ট এডিট করুন (বা আবার আমদানি করুন)।',
    'ops_warn_opening_balances_unverified' => 'শুরুর ব্যালেন্স এখনো নিশ্চিত করা হয়নি। আসল টাকার হিসাব শুরুর আগে এগুলো নিশ্চিত করুন, আর কোনো ব্যালেন্স না থাকলে "নতুন শুরু" বেছে নিন। টেকনিশিয়ানের জন্য: MADINA_FINANCIAL_ACTIVATION।',
    'ops_warn_opening_balances_stale' => 'শুরুর ব্যালেন্স যাচাইয়ের পর হিসাব খাতা বদলেছে। আসল টাকার হিসাব শুরুর আগে শুরুর ব্যালেন্স আবার জমা দিয়ে যাচাই করুন। টেকনিশিয়ানের জন্য: MADINA_FINANCIAL_ACTIVATION।',
    'ops_warn_commission_policy_unreviewed' => 'কমিশন নিয়মের খসড়া হিসাব বিভাগের দ্বিতীয় একজন যাচাই করে প্রকাশ করেননি। আসল টাকার হিসাব শুরুর আগে এটি করুন। টেকনিশিয়ানের জন্য: MADINA_FINANCIAL_ACTIVATION।',
    'ops_warn_partner_benefit_overrides_active' => 'কিছু সক্রিয় পার্টনার কোনো শর্ত ছাড়াই বিশেষ রেটে বেতন বা র‍্যাঙ্ক সুবিধা পান। আসল টাকার হিসাব শুরুর আগে প্রতিটি দেখে নিন, যাতে ভুল করে কোনোটি না থাকে। টেকনিশিয়ানের জন্য: MADINA_FINANCIAL_ACTIVATION।',
    'ops_warn_preview_mode_enabled' => 'ট্রায়াল মোড এখনো চালু। আসল চালুর আগে এটি বন্ধ করতে টেকনিশিয়ানকে বলুন। আসল টাকার হিসাব বন্ধ থাকলেই কেবল ট্রায়াল মোড নিরাপদ। টেকনিশিয়ানের জন্য: MADINA_PREVIEW_MODE=false।',
    'release_reason_quota_auto' => 'এলাকার টার্গেট আপনা থেকে পূরণ হয়েছে',
    'stock_reason_opening_import' => 'অনুমোদিত এক্সেল ফাইল থেকে শুরুর স্টক যোগ করা হয়েছে',
    'stock_reason_initial_onboarding' => 'পণ্য যোগ করার সময় শুরুর স্টক: :reason',
    'payroll_event_prepared' => 'চালু বেতন চুক্তি ও সেভ করা টার্গেট থেকে তৈরি।',
    'acct_default_onboarding_reason' => 'কোম্পানির স্টাফ পার্টনারের যোগদান অনুমোদন করেছেন।',
