    'report_cat_additional_rank_pool' => 'সাব-ডিলার অতিরিক্ত র‍্যাঙ্ক ফান্ড',
    'ops_warn_app_domain_mismatches_app_url' => 'ওয়েবসাইটের ঠিকানা দুই জায়গায় দুই রকম দেওয়া আছে, তাই প্যানেলের লিংক ও পাসওয়ার্ড রিসেট লিংক কাজ নাও করতে পারে। দুটো এক করতে টেকনিশিয়ানকে বলুন। টেকনিশিয়ানের জন্য: APP_DOMAIN ও APP_URL।',
    'ops_warn_payment_collection_accounts_missing' => 'পেমেন্ট নেওয়ার কোনো চালু কোম্পানি অ্যাকাউন্ট নেই। ডিলাররা টাকা পাঠানো শুরুর আগে টাকা নেওয়ার জন্য অন্তত একটি ব্যাংক বা মোবাইল ব্যাংকিং অ্যাকাউন্ট যোগ করুন।',
    'ops_warn_payment_payout_accounts_missing' => 'টাকা পাঠানোর কোনো চালু কোম্পানি অ্যাকাউন্ট নেই। পার্টনাররা আসলে টাকা তোলার আগে টাকা পাঠাতে পারে এমন অন্তত একটি ব্যাংক বা মোবাইল ব্যাংকিং অ্যাকাউন্ট যোগ করুন।',
    'ops_warn_queue_driver_is_sync' => 'পেছনে চলার কাজ সেট করা নেই, তাই এক্সেল থেকে তথ্য আনা ও কিছু পেমেন্ট নিজে থেকে চলবে না। টেকনিশিয়ানকে জানান। টেকনিশিয়ানের জন্য: queue driver এখন sync/null; database বা redis দিন।',
    'ops_warn_scheduler_heartbeat_missing' => 'নির্দিষ্ট সময়ের কাজগুলো চলছে না, তাই কমিশন ছাড়া ও ব্যাকআপ সময়মতো হবে না। টেকনিশিয়ানকে জানান। টেকনিশিয়ানের জন্য: `php artisan schedule:work` (বা cron) চালান।',
    'ops_warn_queue_worker_heartbeat_missing' => 'পেছনের কাজ চালানোর প্রোগ্রাম বন্ধ, তাই এক্সেল থেকে তথ্য আনা ও অন্য কাজ আটকে আছে। টেকনিশিয়ানকে জানান। টেকনিশিয়ানের জন্য: `php artisan queue:work --queue=imports,default` চালান।',
    'ops_warn_debug_mode_enabled' => 'ভুলের বিস্তারিত তথ্য বাইরের লোক দেখতে পারে। আসল ব্যবহারের আগে এটি বন্ধ করতে টেকনিশিয়ানকে বলুন। টেকনিশিয়ানের জন্য: APP_DEBUG=false।',
    'ops_warn_backups_not_configured' => 'তালাবদ্ধ (এনক্রিপ্টেড) ব্যাকআপ চালু নেই। ব্যাকআপ চালু করে একবার পরীক্ষা করতে টেকনিশিয়ানকে বলুন। টেকনিশিয়ানের জন্য: MADINA_BACKUPS_ENABLED, ৩২+ অক্ষরের MADINA_BACKUP_PASSWORD, তারপর app:backup-verify।',
    'ops_warn_app_environment_not_production' => 'সার্ভার লাইভ মোডে নেই। সবার জন্য খোলার আগে এটি ঠিক করতে টেকনিশিয়ানকে বলুন। টেকনিশিয়ানের জন্য: APP_ENV=production।',
    'ops_warn_app_url_not_https' => 'ওয়েবসাইটের ঠিকানা নিরাপদ নয় (https নেই)। আসল ব্যবহারের আগে নিরাপদ https:// ঠিকানা দিতে টেকনিশিয়ানকে বলুন। টেকনিশিয়ানের জন্য: APP_URL।',
    'ops_warn_session_cookies_not_hardened' => 'লাইভ সাইটে লগইন পুরোপুরি সুরক্ষিত নয়। টেকনিশিয়ানকে ঠিক করতে বলুন। টেকনিশিয়ানের জন্য: SESSION_SECURE_COOKIE=true ও SESSION_ENCRYPT=true।',
    'ops_warn_app_key_missing_or_weak' => 'অ্যাপের নিরাপত্তা চাবি নেই বা খুব ছোট। আসল ব্যবহারের আগে শক্ত চাবি তৈরি করতে টেকনিশিয়ানকে বলুন। টেকনিশিয়ানের জন্য: APP_KEY।',
    'ops_warn_trusted_proxies_not_configured' => 'সাইট ভিজিটরের আসল ইন্টারনেট ঠিকানা দেখতে পাচ্ছে না, তাই নিরাপত্তা যাচাই দুর্বল হয়। টেকনিশিয়ানকে জানান। টেকনিশিয়ানের জন্য: TRUSTED_PROXIES-এ প্রক্সি/লোড-ব্যালেন্সারের IP রেঞ্জ দিন।',
    'ops_warn_verified_backup_missing' => 'সম্প্রতি পরীক্ষা করা কোনো ব্যাকআপ নেই। একটি ব্যাকআপ নিয়ে পরীক্ষা করতে টেকনিশিয়ানকে বলুন। টেকনিশিয়ানের জন্য: `php artisan app:backup` তারপর `php artisan app:backup-verify`।',
